// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(address owner, uint256 amount) public {
        // Admissible domain: owner is a plain EOA (accepts ETH transfers),
        // distinct from the contract itself; funding is strictly positive.
        vm.assume(owner.code.length == 0);
        vm.assume(owner != address(c));
        amount = bound(amount, 1, type(uint256).max);

        // Make `owner` the deployer so c.Owner == owner (constructor reads msg.sender).
        vm.prank(owner);
        c = new MultiplicatorX4();

        // Fund the contract directly with the fuzzed amount.
        vm.deal(address(c), amount);

        // Owner calls withdraw(); observe success and the drained balance.
        vm.prank(owner);
        bool ok;
        try c.withdraw{gas: 100000}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful owner withdraw() always succeeds (EOA owner
        // accepts ETH) AND leaves the contract with zero balance.
        assertTrue(ok && address(c).balance == 0);
    }
}
